package ru.genesis.calendar.data

/** A committed local transition; never generated by sync, refresh or historical edits. */
data class HabitFeedbackEvent(val scope: String, val kind: String, val habitTitle: String,
    val settings: HabitFeedbackSettings, val achievements: Int = 0)

val habitSoundSchemes = listOf("calm", "epic", "futuristic")
val habitFeedbackKinds = listOf("completion", "daily-goal", "perfect-day", "achievement", "quest", "rank-up")
fun habitSoundScheme(value: String?) = value?.takeIf { it in habitSoundSchemes } ?: "calm"

internal fun habitFeedbackTransition(scope: String, before: LocalHabitWorkspace,
    after: LocalHabitWorkspace): HabitFeedbackEvent? {
    if (!after.settings.enabled) return null
    val entry = after.completions.lastOrNull { next -> next.completed &&
        before.completions.none { it.habitId == next.habitId && it.date == next.date && it.completed } } ?: return null
    val habit = after.habits.firstOrNull { it.id == entry.habitId } ?: return null
    val achievements = after.achievementUnlocks.count { next ->
        before.achievementUnlocks.none { it.achievementId == next.achievementId } }
    val quest = after.settings.feedback.questsEnabled && after.quests.any { next -> next.completedAt != null &&
        before.quests.none { it.id == next.id && it.completedAt != null } }
    val goal = after.goals.firstOrNull { it.date == entry.date }?.status
    val previousGoal = before.goals.firstOrNull { it.date == entry.date }?.status
    val kind = when {
        after.progress.currentRankId != before.progress.currentRankId -> "rank-up"
        quest -> "quest"
        achievements > 0 && after.settings.feedback.achievementPopups -> "achievement"
        goal == "perfect" && previousGoal != "perfect" -> "perfect-day"
        goal in setOf("qualified", "perfect") && previousGoal !in setOf("qualified", "perfect") -> "daily-goal"
        else -> "completion"
    }
    return HabitFeedbackEvent(scope, kind, habit.title, after.settings.feedback, achievements)
}
